import { useState, useEffect } from "react";

function App() {

  const [score, setScore] = useState(0)
  const [adder, setAdder] = useState(1)

  const addScore = () => {
    setScore(score + adder);
  }

  const upgrade = () => {
    switch(true) {
      case(score === 10):
        setAdder(adder + 2);
        break;
      default:
        break;
    }
  }

  useEffect(() => {
    upgrade()
  }, [score]);

  return (
    <div className="Container">
      <h1>{score}</h1>

      <button onClick={addScore}>+</button>

      <div>
        <h2>Shop</h2>
      </div>
    </div>
  );
}

export default App;
